const profileRender=render;render=()=>{profileRender();renderMosqueIdentity();bindProfile();if(page==='keuangan'&&permitted('finance_categories')){const panel=document.createElement('section');panel.className='panel';panel.innerHTML='<div class="panel-head"><h3>Kategori keuangan</h3></div>'+plainTable([['Nama kategori','Jenis'],...db.finance_categories.map(c=>[c.name,c.kind==='income'?'Pemasukan':'Pengeluaran'])],db.finance_categories.map(c=>actions('finance_categories',c)));$('#main').appendChild(panel)}decorateDeletes();if(mapping[page]&&page!=='pengumuman'&&(page!=='pengurus'||role==='admin')&&(page!=='keuangan'||['admin','takmir','bendahara'].includes(role))){const existing=$('#export');if(existing){existing.textContent='Ekspor ▾';existing.onclick=chooseCoreExport}else{$('.page-top')?.insertAdjacentHTML('beforeend','<button id="core-report" class="secondary">Ekspor ▾</button>');$('#core-report')?.addEventListener('click',chooseCoreExport)}}if(['inventaris','pengurus'].includes(page)){const add=$('.page-top [data-add]'),exp=$('#core-report');if(exp){const group=document.createElement('div');group.className='page-actions';group.setAttribute('role','group');group.setAttribute('aria-label','Aksi '+page);exp.before(group);group.append(exp);if(add)group.append(add)}}};
const listingWithDelete=renderListing;renderListing=()=>{listingWithDelete();decorateDeletes()};
