const oldOpenEvent=openEvent;openEvent=id=>{oldOpenEvent(id);const edit=$('[data-ui-event-edit]');if(edit&&permitted('events'))edit.insertAdjacentHTML('afterend',deleteButton('events',id))};

// weight_kg remains the total used by reports, collected totals and dashboard graphs.
function distributionTotal(count,weight){const n=Number(count),w=Number(weight);if(!Number.isInteger(n)||n<1||n>1000000||!Number.isFinite(w)||w<=0||Math.abs(w*1000-Math.round(w*1000))>0.00001)throw Error('Jumlah paket harus bilangan bulat 1–1.000.000; berat per paket harus positif, maksimal 3 desimal.');const total=n*Math.round(w*1000)/1000;if(total>999999999.999)throw Error('Total berat melebihi batas 999.999.999,999 kg.');return total}
function validateDistribution(d){if(!Number.isInteger(Number(d.year))||d.year<2000||d.year>2200)throw Error('Tahun harus 2000–2200.');for(const [k,min,max,label] of [['rt_name',1,100,'Nama RT'],['village',2,200,'Desa/Dusun'],['rt_rw',1,100,'RW/RT']]){const value=String(d[k]??'').trim();if(value.length<min||value.length>max)throw Error(label+' wajib diisi (maksimal '+max+' karakter).')}distributionTotal(d.package_count,d.package_weight_kg)}
function distributionFields(r){return yearField(r)+field('rt_name','Nama RT',r.rt_name||'','text','required maxlength="100"')+field('village','Desa/Dusun',r.village||'','text','required minlength="2" maxlength="200"')+field('rt_rw','RW/RT',r.rt_rw||'','text','required maxlength="100" placeholder="Contoh: RT 01 / RW 02"')+field('package_count','Jumlah Paket',r.package_count??1,'number','required min="1" max="1000000" step="1"')+field('package_weight_kg','Berat per Paket (kg)',r.package_weight_kg??r.weight_kg??2,'number','required min="0.001" max="999999999.999" step="0.001"')+field('weight_kg','Total Berat (kg)',r.weight_kg??2,'number','readonly aria-describedby="distribution-formula"')+'<p id="distribution-formula" class="note" aria-live="polite">Total berat = jumlah paket × berat per paket.</p>'+(!r.village&&r.id?`<p class="note">Arsip lama: ${esc(r.recipient||'')} · ${esc(r.address||'')}. Total lama dipertahankan sebagai 1 paket. Lengkapi Desa/Dusun dan RW/RT saat mengedit.</p>`:'')+`<p class="note">Nomor distribusi dibuat otomatis. ${r.collected_at?'Sudah diserahkan.':''}</p>`}
function bindDistributionForm(f){const update=()=>{try{const total=distributionTotal(f.elements.package_count.value,f.elements.package_weight_kg.value);f.elements.weight_kg.value=total;$('#distribution-formula').textContent=fmt(Number(f.elements.package_count.value))+' paket × '+fmt(Number(f.elements.package_weight_kg.value))+' kg = '+fmt(total)+' kg';}catch(err){f.elements.weight_kg.value='';$('#distribution-formula').textContent=err.message}};f.elements.package_count.oninput=update;f.elements.package_weight_kg.oninput=update;update()}
const distributionReportRows=reportRows;
reportRows=(t,rows=scoped(t))=>t!=='qurban_distribution'?distributionReportRows(t,rows):[['Tahun','Nomor distribusi','Nama RT','Desa/Dusun','RW/RT','Jumlah Paket','Berat per Paket (kg)','Total Berat (kg)','Status','Waktu diambil'],...rows.map(r=>[r.year,r.coupon,r.rt_name||'—',r.village||r.address||'Arsip lama',r.rt_rw||'—',r.package_count??1,Number(r.package_weight_kg??r.weight_kg),Number(r.weight_kg),r.collected_at?'Sudah diambil':'Belum diambil',r.collected_at?new Date(r.collected_at).toLocaleString('id-ID'):'—'])];
zakatHeaders.qurban_distribution=['Tahun Kegiatan','Nama RT','Desa/Dusun','RW/RT','Jumlah Paket','Berat per Paket (kg)','Total Berat (kg)'];
const packageTemplate=downloadZakatTemplate;
downloadZakatTemplate=()=>{if(section!=='qurban_distribution')return packageTemplate();downloadBlob(SimasExport.xlsx([{name:'Data',rows:[zakatHeaders.qurban_distribution]},{name:'Petunjuk',rows:[['Kolom','Ketentuan'],['Tahun Kegiatan','2000–2200'],['Nama RT','Wajib; maksimal 100 karakter'],['Desa/Dusun','Wajib; 2–200 karakter'],['RW/RT','Wajib; maksimal 100 karakter'],['Jumlah Paket','Bilangan bulat positif, maksimal 1000000'],['Berat per Paket (kg)','Positif, maksimal 3 desimal. Contoh 2.5'],['Total Berat (kg)','Boleh dikosongkan: dihitung otomatis. Jika diisi harus sama dengan jumlah paket × berat per paket. Tanpa formula Excel.'],['Contoh','25 paket × 2.5 kg = 62.5 kg'],['Impor','Maksimal 1000 baris / 2 MB. Template lama tidak berlaku; unduh template terbaru.']]}]),'Template-Distribusi-Qurban.xlsx')};
const packageParser=parseZakatRows;
parseZakatRows=(matrix,t)=>{if(t!=='qurban_distribution')return packageParser(matrix,t);const records=[],errors=[],seen=new Set(),str=v=>String(v??'').trim();if(JSON.stringify((matrix[0]||[]).map(str))!==JSON.stringify(zakatHeaders[t]))return {records,errors:['Kolom tidak sesuai. Unduh template Distribusi terbaru (jumlah paket dan berat per paket).']};if(matrix.length>1001)return {records,errors:['Maksimal 1000 baris per impor.']};matrix.slice(1).forEach((a,i)=>{if(a.every(v=>!str(v)))return;try{const d={year:Number(a[0]),rt_name:str(a[1]),village:str(a[2]),rt_rw:str(a[3]),package_count:Number(a[4]),package_weight_kg:Number(a[5])};if(a.slice(7).some(v=>str(v)))throw Error('Ada kolom tambahan.');validateDistribution(d);d.weight_kg=distributionTotal(d.package_count,d.package_weight_kg);if(str(a[6])&&(!Number.isFinite(Number(a[6]))||Math.abs(Number(a[6])-d.weight_kg)>0.000001))throw Error('Total berat tidak sama dengan jumlah paket × berat per paket.');const key=JSON.stringify(d);if(seen.has(key)||db.qurban_distribution.some(r=>Object.keys(d).every(k=>String(r[k]??'')===String(d[k]??''))))throw Error('Distribusi identik sudah tercatat.');seen.add(key);records.push({...d,coupon:newCoupon(d.year)})}catch(err){errors.push('Baris '+(i+2)+': '+err.message)}});if(!records.length&&!errors.length)errors.push('Sheet Data belum berisi data.');return {records,errors}};

