 const options=db.zakat_people.filter(p=>p.person_type===roleName).map(p=>[p.id,p.full_name+' · '+(p.village||p.address||'Alamat belum diisi')+(p.rt_rw?' · '+p.rt_rw:'')]);
 const kinds=Object.entries(zakatKindLabels).filter(([k])=>distribution||k!=='fitrah_mal');
 const legacyCash=r.zakat_type==='fitrah'&&Number(r.amount)>0;
