 '<p class="note">Data jamaah diperbarui otomatis setelah transaksi berhasil disimpan. Nama baru menjadi '+(distribution?'Mustahik':'Muzakki')+'.</p><p id="form-error" class="error-text" role="alert"></p><button type="submit" class="primary">Simpan data</button>';
 const f=$('#form'),sync=()=>{const k=f.elements.zakat_type.value;for(const [name,on] of [['rice_kg',k!=='mal'],['amount',k!=='fitrah'||legacyCash]]){const el=f.elements[name];el.disabled=!on;el.required=on;el.closest('label').hidden=!on;}if(legacyCash&&k==='fitrah'){f.elements.rice_kg.required=false;f.elements.rice_kg.min='0';}};
