 const t=section;
 uiDialog('Import Excel · '+tableNames[t],'<p>Gunakan template menu ini. Semua baris diperiksa sebelum disimpan.</p><label>Berkas Excel (.xlsx)<input id="flow-file" type="file" accept=".xlsx"></label><div id="flow-preview"></div><div id="flow-duplicates" class="note" hidden role="status"></div><p id="flow-error" role="alert" class="error-text"></p><div class="action-buttons"><button class="primary" id="flow-save" disabled>Simpan hasil impor</button><button class="secondary" id="flow-cancel">Batal / perbaiki berkas</button></div>');
